#ifndef SERVAL_SPRITES_H
#define SERVAL_SPRITES_H

// Sprite assets, sprite groups and drawing. See docs/sprites.md.
//
// Sprite data lives in ROM as constant tables, normally generated by Studio
// Advance's build. Games refer to sprites by ID: an index into the sprite table
// registered with sprite_table_set(). A sprite can be drawn once a group
// containing it has been loaded into VRAM.

#include "serval/platform.h"

// SpriteAsset.shape and .size select the hardware sprite dimensions:
//            size 0   size 1   size 2   size 3
//   SQUARE    8x8     16x16    32x32    64x64
//   WIDE     16x8     32x8     32x16    64x32
//   TALL      8x16     8x32    16x32    32x64
#define SPRITE_SHAPE_SQUARE 0
#define SPRITE_SHAPE_WIDE 1
#define SPRITE_SHAPE_TALL 2

// SpriteAsset.flags
#define SPRITE_ASSET_STREAMED (1 << 0)   // not supported yet
#define SPRITE_ASSET_METASPRITE (1 << 1) // not supported yet

typedef struct {
    u8 shape, size;        // SPRITE_SHAPE_*, 0-3
    u8 frame_count;        // animation frames
    u8 tiles_per_frame;    // 8x8 4bpp tiles per frame
    const u32* tiles;      // frame_count * tiles_per_frame tiles, 8 words each
    const u8* frame_times; // animation timing, may be NULL
    s8 origin_x, origin_y; // drawn position = (x, y) - origin
    u8 palette_slot;       // logical palette bank within its group
    u8 flags;              // SPRITE_ASSET_*
} SpriteAsset;

// SpriteGroup.flags
#define SPRITE_GROUP_RESIDENT (1 << 0) // all frames copied to VRAM on load (the only mode so far)

typedef struct {
    u8 sprite_count, palette_count, flags;
    const u16* sprite_ids; // IDs (sprite table indices) of the group's sprites
    const u16* palettes;   // palette_count banks of 16 colors (index 0 transparent)
    u16 tile_count;        // total tiles of all sprites in the group
} SpriteGroup;

// Most sprite IDs a sprite table may hold.
#define SPRITE_MAX 512

// sprite_draw() flags
#define SPRITE_FLIP_H (1 << 0)
#define SPRITE_FLIP_V (1 << 1)
#define SPRITE_PRIORITY(n) (((n) & 3) << 2) // 0 (front) to 3; relative to backgrounds

// Registers the game's sprite table: table[id] is the sprite with that ID.
// Unloads all sprite groups.
void sprite_table_set(const SpriteAsset* const* table, u16 count);

// Copies a group's tiles and palettes to VRAM so its sprites can be drawn.
// Returns false, leaving nothing loaded from this group, if sprite VRAM or
// palette banks would run out or the group uses an unsupported feature.
bool sprite_group_load(const SpriteGroup* group);

// Unloads every sprite group, freeing all sprite VRAM and palette banks.
void sprite_groups_reset(void);

// Draws a frame of a sprite this frame. Does nothing if the sprite is not
// loaded, the frame does not exist, it is fully off screen, or all hardware
// sprites are used.
void sprite_draw(u16 sprite_id, u8 frame, int x, int y, u16 flags);

#endif // SERVAL_SPRITES_H
